PRAGMA foreign_keys = ON;
CREATE TABLE IF NOT EXISTS users (id TEXT PRIMARY KEY, username TEXT NOT NULL UNIQUE, display_name TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('FOUNDER','ORGANIZER','MEMBER')), password_hash TEXT, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS events (id TEXT PRIMARY KEY, title TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', start_at TEXT NOT NULL, end_at TEXT NOT NULL DEFAULT '', location TEXT NOT NULL DEFAULT '', status TEXT NOT NULL DEFAULT 'DRAFT' CHECK(status IN ('DRAFT','PUBLISHED')), created_by TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS activities (id TEXT PRIMARY KEY, name TEXT NOT NULL, description TEXT NOT NULL DEFAULT '', category TEXT NOT NULL, rules TEXT NOT NULL DEFAULT '', materials TEXT NOT NULL DEFAULT '', duration TEXT NOT NULL DEFAULT '', age_suitability TEXT NOT NULL DEFAULT 'All ages', created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS event_activities (event_id TEXT NOT NULL, activity_id TEXT NOT NULL, position INTEGER NOT NULL DEFAULT 0, PRIMARY KEY(event_id,activity_id), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, FOREIGN KEY(activity_id) REFERENCES activities(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS event_registrations (id TEXT PRIMARY KEY, event_id TEXT NOT NULL, user_id TEXT NOT NULL, response TEXT NOT NULL CHECK(response IN ('GOING','MAYBE','CANT_ATTEND')), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP, UNIQUE(event_id,user_id), FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE, FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS attendance (id TEXT PRIMARY KEY,event_id TEXT NOT NULL,user_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'PRESENT',marked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(event_id,user_id),FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS sessions (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,expires_at TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS organizer_permissions (user_id TEXT NOT NULL,permission TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,PRIMARY KEY(user_id,permission),FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS member_profiles (user_id TEXT PRIMARY KEY,bio TEXT NOT NULL DEFAULT '',avatar_url TEXT NOT NULL DEFAULT '',member_since TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS competitions (id TEXT PRIMARY KEY,event_id TEXT,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'DRAFT',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS competition_rounds (id TEXT PRIMARY KEY,competition_id TEXT NOT NULL,name TEXT NOT NULL,position INTEGER NOT NULL DEFAULT 0,FOREIGN KEY(competition_id) REFERENCES competitions(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS competition_participants (competition_id TEXT NOT NULL,user_id TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'REGISTERED',PRIMARY KEY(competition_id,user_id),FOREIGN KEY(competition_id) REFERENCES competitions(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS competition_results (id TEXT PRIMARY KEY,competition_id TEXT NOT NULL,round_id TEXT,user_id TEXT NOT NULL,position INTEGER,score TEXT NOT NULL DEFAULT '',published INTEGER NOT NULL DEFAULT 0,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,UNIQUE(competition_id,round_id,user_id),FOREIGN KEY(competition_id) REFERENCES competitions(id) ON DELETE CASCADE,FOREIGN KEY(round_id) REFERENCES competition_rounds(id) ON DELETE SET NULL,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS achievements (id TEXT PRIMARY KEY,name TEXT NOT NULL UNIQUE,description TEXT NOT NULL DEFAULT '',icon TEXT NOT NULL DEFAULT '🏆',requirement TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS member_achievements (achievement_id TEXT NOT NULL,user_id TEXT NOT NULL,awarded_by TEXT,awarded_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,source_type TEXT NOT NULL DEFAULT 'MANUAL',source_id TEXT,PRIMARY KEY(achievement_id,user_id),FOREIGN KEY(achievement_id) REFERENCES achievements(id) ON DELETE CASCADE,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE,FOREIGN KEY(awarded_by) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS notifications (id TEXT PRIMARY KEY,user_id TEXT NOT NULL,type TEXT NOT NULL DEFAULT 'GENERAL',title TEXT NOT NULL,message TEXT NOT NULL DEFAULT '',link TEXT NOT NULL DEFAULT '',read_at TEXT,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS notification_preferences (user_id TEXT PRIMARY KEY,events INTEGER NOT NULL DEFAULT 1,achievements INTEGER NOT NULL DEFAULT 1,competitions INTEGER NOT NULL DEFAULT 1,announcements INTEGER NOT NULL DEFAULT 1,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE IF NOT EXISTS announcements (id TEXT PRIMARY KEY,title TEXT NOT NULL,message TEXT NOT NULL,audience TEXT NOT NULL DEFAULT 'MEMBERS',status TEXT NOT NULL DEFAULT 'DRAFT',event_id TEXT,published_at TEXT,created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,updated_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS albums (id TEXT PRIMARY KEY,event_id TEXT,title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',visibility TEXT NOT NULL DEFAULT 'MEMBERS',created_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(event_id) REFERENCES events(id) ON DELETE SET NULL,FOREIGN KEY(created_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS photos (id TEXT PRIMARY KEY,album_id TEXT NOT NULL,url TEXT NOT NULL,caption TEXT NOT NULL DEFAULT '',uploaded_by TEXT NOT NULL,created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(album_id) REFERENCES albums(id) ON DELETE CASCADE,FOREIGN KEY(uploaded_by) REFERENCES users(id));
CREATE TABLE IF NOT EXISTS audit_logs (id TEXT PRIMARY KEY,user_id TEXT,action TEXT NOT NULL,entity_type TEXT NOT NULL,entity_id TEXT,details TEXT NOT NULL DEFAULT '',created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE INDEX IF NOT EXISTS idx_events_start ON events(start_at); CREATE INDEX IF NOT EXISTS idx_registrations_event ON event_registrations(event_id); CREATE INDEX IF NOT EXISTS idx_attendance_user ON attendance(user_id); CREATE INDEX IF NOT EXISTS idx_notifications_user ON notifications(user_id,created_at); CREATE INDEX IF NOT EXISTS idx_member_achievements_user ON member_achievements(user_id,awarded_at); CREATE INDEX IF NOT EXISTS idx_announcements_status ON announcements(status,published_at); CREATE INDEX IF NOT EXISTS idx_photos_album ON photos(album_id,created_at); CREATE INDEX IF NOT EXISTS idx_audit_logs_created ON audit_logs(created_at);
